const sensor = $('Set Sensor Data Parameters').first().json;
const weather =$input.first().json;

const past24hRainMm = weather.daily?.precipitation_sum?.[0] ?? 0.0;
const forecast48hRainMm = (weather.daily?.precipitation_sum?.[1] ?? 0) + (weather.daily?.precipitation_sum?.[2] ?? 0);
const rainProbabilityMax = weather.daily?.precipitation_probability_max?.[1] ?? 0;
const maxTempC = weather.daily?.temperature_2m_max?.[1] ?? 25;

return [{
  json: {
    sensorData: {
      zoneId: sensor.zoneId,
      cropType: sensor.cropType,
      moisturePercent: sensor.moisturePercent,
      thresholdPercent: sensor.thresholdPercent,
      pumpState: sensor.pumpState,
      lastRunHoursAgo: sensor.lastRunHoursAgo
    },
    weatherContext: {
      past24hRainMm,
      forecast48hRainMm,
      rainProbabilityMax,
      maxTempC
    },
    promptInput: `Analyze this agronomic telemetry incident:
- Zone: ${sensor.zoneId} (${sensor.cropType})
- Soil Moisture: ${sensor.moisturePercent}% (Critical Target Threshold: ${sensor.thresholdPercent}%)
- Pump Status: ${sensor.pumpState}
- Hours Since Last Irrigation Cycle: ${sensor.lastRunHoursAgo} hours
- Past 24h Rain: ${past24hRainMm} mm
- Upcoming 48h Rain Forecast: ${forecast48hRainMm} mm (${rainProbabilityMax}% chance)
- Peak Ambient Temp: ${maxTempC}°C

Evaluate root-zone water stress, pinpoint hardware or scheduling faults, determine escalation severity, calculate SLA window, and draft operational work orders.`
  }
}];

const rawOutput = $input.first().json.output;
const parsed = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : (rawOutput || {});

// Fetch context safely with fallbacks
let context = {};
try {
  context = $('Prepare AI Input Prompt').first().json || {};
} catch (e) {
  context = {};
}

const sensorData = context.sensorData || {};
const weatherContext = context.weatherContext || {};

// Normalize severity
const state = String(parsed.state ?? '').trim().toUpperCase();
const rawSeverity = String(parsed.severity ?? '').trim().toUpperCase();

const severity =
  ['CRITICAL', 'HIGH', 'ADVISORY', 'NORMAL'].includes(rawSeverity)
    ? rawSeverity
    : (state.includes('CRITICAL') ? 'CRITICAL' :
       state.includes('HIGH') ? 'HIGH' :
       state.includes('ADVISORY') || state.includes('RAIN') ? 'ADVISORY' :
       'NORMAL');

// Normalize SLA hours safely (handles both numbers and strings like "4 hours")
let slaResponseHours = 0;
if (typeof parsed.slaResponseHours === 'number') {
  slaResponseHours = parsed.slaResponseHours;
} else if (parsed.slaResponseHours) {
  const match = String(parsed.slaResponseHours).match(/(\d+(?:\.\d+)?)/);
  slaResponseHours = match ? Number(match[1]) : 0;
}

// Preserve LLM evaluation or infer if omitted
const requiresEscalation = typeof parsed.requiresEscalation === 'boolean'
  ? parsed.requiresEscalation
  : severity !== 'NORMAL';

// Fallback incident title
const incidentTitle =
  parsed.incidentTitle ||
  parsed.title ||
  (state ? state.replace(/_/g, ' ').trim() : 'Irrigation Incident');

// Construct unique ticket identifier safely
const zoneId = sensorData.zoneId || 'ZONE-UNKNOWN';
const ticketId = `IRR-${zoneId}-${Date.now().toString(36).toUpperCase()}`;

return [{
  json: {
    ...parsed,
    state,
    severity,
    incidentTitle,
    rootCauseAnalysis: parsed.rootCauseAnalysis || 'No root cause supplied by the evaluator.',
    actionItems: Array.isArray(parsed.actionItems) ? parsed.actionItems : [],
    slaResponseHours,
    requiresEscalation,
    sensorData,
    weatherContext,
    ticketId,
    evaluationTimestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;

const resolutionDeadline = item.slaResponseHours > 0 
  ? new Date(Date.now() + item.slaResponseHours * 3600 * 1000).toISOString()
  : 'N/A';

const formattedWorkOrder = {
  ticketId: item.ticketId,
  status: item.workOrderStatus,
  priority: item.severity,
  issueTitle: item.incidentTitle,
  zone: item.sensorData.zoneId,
  crop: item.sensorData.cropType,
  urgency: item.dispatchUrgency,
  channel: item.escalationChannel,
  assignee: item.targetAudience,
  slaHours: item.slaResponseHours,
  slaDeadline: resolutionDeadline,
  rootCause: item.rootCauseAnalysis,
  prescribedActions: item.actionItems,
  telemetrySnapshot: item.sensorData,
  weatherSnapshot: item.weatherContext
};

return [{
  json: {
    status: 'SUCCESS',
    incidentProcessed: true,
    requiresIntervention: item.requiresEscalation,
    severity: item.severity,
    ticket: formattedWorkOrder
  }
}];

